def init_params(key):
    """Xavier/Kaiming uniform init."""
    params = []
    # ConvBN 3→32, 3x3
    key, k_ = random.split(key)
    scale = jnp.sqrt(6.0 / 288)
    params.append((random.uniform(k_, (32, 3, 3, 3), minval=-scale, maxval=scale),
                   jnp.ones(32), jnp.zeros(32)))
    # FMB fused 32→128, 3x3
    key, k_ = random.split(key)
    scale = jnp.sqrt(6.0 / 1152)
    params.append((random.uniform(k_, (128, 32, 3, 3), minval=-scale, maxval=scale),
                   jnp.ones(128), jnp.zeros(128)))
    # FMB project 128→48
    key, k_ = random.split(key)
    scale = jnp.sqrt(6.0 / 48)
    params.append((random.uniform(k_, (48, 128, 1, 1), minval=-scale, maxval=scale),
                   jnp.ones(48), jnp.zeros(48)))
