def forward(params, x, bn, training, drop_key=None):
    bn_out = []
    bn_i = 0
    x = x.reshape(-1, 3, 224, 224)
    dpkeys = (jax.random.split(drop_key, 21) if drop_key is not None else [None] * 21)
    x, _ns = conv_bn(x, params[0][0], params[0][1], params[0][2], bn[bn_i], training, stride=(2,2), padding='SAME')
    bn_out.append(_ns); bn_i += 1
    x = jax.nn.relu(x)
    x, _ne = fused_mbconv_block(params, x, 1, 2, 4, 3, False, bn, bn_i, training)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 3, 2, 3, 5, bn, bn_i, training, dpkeys[0], 1.000000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 7, 1, 3, 3, bn, bn_i, training, dpkeys[1], 0.996250)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 11, 2, 3, 5, bn, bn_i, training, dpkeys[2], 0.992500)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 15, 1, 3, 3, bn, bn_i, training, dpkeys[3], 0.988750)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 19, 1, 3, 3, bn, bn_i, training, dpkeys[4], 0.985000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 23, 1, 3, 5, bn, bn_i, training, dpkeys[5], 0.981250)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 27, 1, 3, 3, bn, bn_i, training, dpkeys[6], 0.977500)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 31, 1, 3, 0, bn, bn_i, training, dpkeys[7], 0.973750)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 34, 1, 0, 0, bn, bn_i, training, dpkeys[8], 0.970000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 36, 1, 3, 0, bn, bn_i, training, dpkeys[9], 0.966250)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 39, 2, 5, 5, bn, bn_i, training, dpkeys[10], 0.962500)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 43, 1, 5, 5, bn, bn_i, training, dpkeys[11], 0.958750)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 47, 1, 3, 5, bn, bn_i, training, dpkeys[12], 0.955000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 51, 1, 3, 5, bn, bn_i, training, dpkeys[13], 0.951250)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 55, 1, 0, 0, bn, bn_i, training, dpkeys[14], 0.947500)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 57, 1, 3, 0, bn, bn_i, training, dpkeys[15], 0.943750)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 60, 1, 3, 5, bn, bn_i, training, dpkeys[16], 0.940000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 64, 1, 5, 5, bn, bn_i, training, dpkeys[17], 0.936250)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 68, 1, 0, 0, bn, bn_i, training, dpkeys[18], 0.932500)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 70, 1, 0, 0, bn, bn_i, training, dpkeys[19], 0.928750)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ne = uib_block(params, x, 72, 1, 5, 0, bn, bn_i, training, dpkeys[20], 0.925000)
    bn_out.extend(_ne); bn_i += len(_ne)
    x, _ns = conv_bn(x, params[75][0], params[75][1], params[75][2], bn[bn_i], training, padding='SAME')
    bn_out.append(_ns); bn_i += 1
    x = jax.nn.relu(x)
    x, _ns = conv_bn(x, params[76][0], params[76][1], params[76][2], bn[bn_i], training, padding='SAME')
    bn_out.append(_ns); bn_i += 1
    x = jax.nn.relu(x)
    x = global_avg_pool(x)
    if drop_key is not None:
        x = x * jax.random.bernoulli(jax.random.fold_in(drop_key, 999983), 0.800000, x.shape).astype(x.dtype) / 0.800000
    x = mm(x, params[77][0].T) + params[77][1]
    return x, bn_out

def loss_fn(params, bn, x, y, drop_key=None):
    logits, _new_bn = forward(params, x, bn, True, drop_key)
    log_probs = jax.nn.log_softmax(logits, axis=-1)
    # y is int32 [B] (hard labels) or float [B,NC] (soft labels, mixup/cutmix).
    # y.ndim is static at trace time, so this branch is jit-safe.
    if y.ndim == 1:
        tgt = jax.nn.one_hot(y, 1000)
        tgt = tgt * (1.0 - 0.100000) + 0.100000 / 1000
    else:
        tgt = y
    return -jnp.mean(jnp.sum(log_probs * tgt, axis=-1)), _new_bn

def augment_batch(x, rng):
    """Random crop (numpy, CPU): pad 224→252, crop back to 224x224."""
    x = x.reshape(-1, 3, 224, 224)
    x = np.pad(x, ((0,0), (0,0), (14,14), (14,14)))
    top = rng.randint(0, 29)
    left = rng.randint(0, 29)
    x = x[:, :, top:top+224, left:left+224]
    return x.reshape(x.shape[0], -1)

# ═══════════════════════════════════════════════════════════════════════
#  Training  (Adam + cosine LR)
# ═══════════════════════════════════════════════════════════════════════

LR = 0.004000
GRAD_ACCUM = 8
WD = 0.100000
_WD_POS_SHAPE = None
def _wd_mask(params):
    # timm no_weight_decay: no decay on 1-D params (biases, LayerNorm γ/β,
    # CLS token) or the positional embedding (2-D but must not be decayed).
    def _leaf(p):
        if p.ndim <= 1: return jnp.zeros_like(p)
        if p.shape == _WD_POS_SHAPE: return jnp.zeros_like(p)
        return jnp.ones_like(p)
    return jax.tree.map(_leaf, params)

@jit
def train_step(params, opt_state, bn, x, y, lr, drop_key=None):
    _K = GRAD_ACCUM
    _xs = x.reshape(_K, x.shape[0] // _K, *x.shape[1:])
    _ys = y.reshape(_K, y.shape[0] // _K, *y.shape[1:])
    _xs = jax.lax.with_sharding_constraint(_xs, NamedSharding(mesh, P(None, 'batch')))
    _ys = jax.lax.with_sharding_constraint(_ys, NamedSharding(mesh, P(None, 'batch')))
    _ks = jax.random.split(drop_key, _K)
    def _accum(_carry, _inp):
        _gacc, _bnc = _carry
        _xi, _yi, _ki = _inp
        (_l, _nbn), _g = value_and_grad(loss_fn, has_aux=True)(params, _bnc, _xi, _yi, _ki)
        return (jax.tree.map(jnp.add, _gacc, _g), _nbn), _l
    _g0 = jax.tree.map(jnp.zeros_like, params)
    (_gsum, _new_bn), _ls = jax.lax.scan(_accum, (_g0, bn), (_xs, _ys, _ks))
    grads = jax.tree.map(lambda _a: _a / _K, _gsum)
    loss = jnp.mean(_ls)
    m, v, t = opt_state
    t = t + 1
    m = jax.tree.map(lambda mi, g: 0.9 * mi + 0.1 * g, m, grads)
    v = jax.tree.map(lambda vi, g: 0.999 * vi + 0.001 * g * g, v, grads)
    mc = jax.tree.map(lambda mi: mi / (1 - 0.9 ** t), m)
    vc = jax.tree.map(lambda vi: vi / (1 - 0.999 ** t), v)
    params = jax.tree.map(lambda p, mi, vi, msk: p - lr * (mi / (jnp.sqrt(vi) + 1e-8) + WD * msk * p), params, mc, vc, WD_MASK)
    return params, (m, v, t), _new_bn, loss

EMA_DECAY = 0.999900
# Warmup-corrected decay, matching TF's tf.train.ExponentialMovingAverage(decay,
# num_updates) — the EMA this net family (MobileNet/EfficientNet, TF lineage) is
# defined against. Without it the shadow starts AT THE RANDOM INIT and decays that
# init away only as decay^t, so a run shorter than ~10 time constants evaluates a
# weighted average of init and trained weights. Those two are not linearly
# connected (there is a loss barrier between them), so the result is not merely
# degraded — it sits at chance.
#
# Measured on MNv4-Conv-M 100ep (2026-07-31): decay 0.9999 = tau 10k steps, but
# gradAccum 8 leaves only 312 optimizer steps/epoch = 31.2k total = 3.1 tau. At
# epoch 66 the shadow still held 12.8% init and scored 0.00% top-1, while the LIVE
# weights scored 70.48% on full 50k. Eval and .bin checkpoints both read the EMA,
# so the run looked like a total failure when only the shadow was broken.
#
# min(decay, (1+t)/(10+t)) ramps from 0.09 at t=0, so the shadow tracks the live
# weights from the first step and reaches the nominal decay once t >> 10. Long runs
# (ENet-B0 350ep = 175 tau) are unaffected either way; short/grad-accum tiers need it.
@jit
def ema_update(ema, params, step):
    d = jnp.minimum(EMA_DECAY, (1.0 + step) / (10.0 + step))
    return jax.tree.map(lambda e, p: d * e + (1.0 - d) * p, ema, params)

@jit
def eval_batch(params, bn, x, y, take):
    logits, _ = forward(params, x, bn, False)
    keep = jnp.arange(logits.shape[0]) < take
    preds = jnp.argmax(logits, axis=-1)
    log_probs = jax.nn.log_softmax(logits, axis=-1)
    loss = -(jnp.sum(jnp.sum(log_probs * jax.nn.one_hot(y, 1000), axis=-1) * keep) / jnp.maximum(take, 1))
    correct1 = jnp.sum((preds == y) & keep)
    # top-5: jax.lax.top_k's indices are broken on ROCm/gfx1100 (garbage on
    # device, HIP error to host), so rank the true class instead — top-5 is
    # correct iff fewer than 5 classes have a strictly-greater logit.
    true_logit = jnp.take_along_axis(logits, y[:, None], axis=1)
    correct5 = jnp.sum((jnp.sum(logits > true_logit, axis=1) < 5) & keep)
    return correct1, correct5, loss

def evaluate(params, images, labels, batch_size=512):
    batch_size = (batch_size // n_devices) * n_devices or n_devices
    _p = np.random.default_rng(12345).permutation(len(labels))
    images, labels = images[_p], labels[_p]
    correct1 = 0
    correct5 = 0
    total_loss = 0.0
    n_batches = 0
    for i in range(0, len(images), batch_size):
        xb, yb = images[i:i+batch_size], labels[i:i+batch_size]
        take = len(yb)
        if take < batch_size:
            pad = batch_size - take
            xb = np.concatenate([xb, images[:pad]], axis=0)
            yb = np.concatenate([yb, labels[:pad]], axis=0)
        c1, c5, l = eval_batch(params,
            jax.device_put(xb, data_sharding),
            jax.device_put(yb, data_sharding),
            take)
        correct1 += int(c1)
        correct5 += int(c5)
        total_loss += float(l)
        n_batches += 1
    evaluated = len(labels)
    return correct1, correct5, evaluated, total_loss / max(n_batches, 1)

